/* SPDX-License-Identifier: GPL-3.0-only */
#include <assert.h>
#include <string.h>
#include "app/smk_apc40.h"

static uint8_t g_channel[SMK_APC40_CLIP_COUNT];   /* APC display mode per cell */

static void test_eight_by_four_crops_viewport_margin(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips, pad;
    /* An 8x4 project begins on APC row 1 inside the controller's fixed 5-row view. */
    for (pad = 8u; pad < 40u; pad++)
        assert(smk_apc40_feedback_set(velocity, g_channel, pad, 0u, (uint8_t)(pad + 1u)));
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 8u && rows == 4u && origin_col == 0u && origin_row == 1u && has_clips);
    for (pad = 0u; pad < 8u; pad++) {
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, pad) == (uint8_t)(8u + pad));
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, (uint8_t)(pad + 8u)) ==
               (uint8_t)(16u + pad));
    }
}

static void test_four_by_four_folds_into_one_eight_by_two_grid(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips, row, col;
    for (row = 1u; row < 5u; row++) {
        for (col = 2u; col < 6u; col++) {
            uint8_t note = (uint8_t)(row * 8u + col);
            assert(smk_apc40_feedback_set(velocity, g_channel, note, (uint8_t)(row & 1u),
                                          (uint8_t)(20u + note)));
        }
    }
    /* An empty cell inside the matrix remains at its coordinate. */
    assert(smk_apc40_feedback_set(velocity, g_channel, 27u, 15u, 0u));
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 4u && rows == 4u && origin_col == 2u && origin_row == 1u && has_clips);

    /* Physical pads 1-4 and 9-12 contain source rows 2-3 (here APC rows 3-4). */
    for (col = 0u; col < 4u; col++) {
        uint8_t upper_logical = smk_apc40_logical_pad_for_physical(col);
        uint8_t lower_logical = smk_apc40_logical_pad_for_physical((uint8_t)(col + 8u));
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, upper_logical) ==
               (uint8_t)(34u + col));
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, lower_logical) ==
               (uint8_t)(26u + col));
    }
    /* Source rows 0-1 occupy physical pads 5-8 and 13-16. */
    for (col = 0u; col < 4u; col++) {
        uint8_t upper_logical = smk_apc40_logical_pad_for_physical((uint8_t)(col + 4u));
        uint8_t lower_logical = smk_apc40_logical_pad_for_physical((uint8_t)(col + 12u));
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, upper_logical) ==
               (uint8_t)(18u + col));
        assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, lower_logical) ==
               (uint8_t)(10u + col));
    }
    assert(velocity[27u] == 0u); /* callers leave this mapped pad black and unlaunchable */
}

static void test_sparse_eight_wide_cells_keep_relative_gaps(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips;
    assert(smk_apc40_feedback_set(velocity, g_channel, 9u, 0u, 60u));   /* row 1, column 1 */
    assert(smk_apc40_feedback_set(velocity, g_channel, 11u, 1u, 61u));  /* row 1, column 3 */
    assert(smk_apc40_feedback_set(velocity, g_channel, 25u, 15u, 62u)); /* row 3, column 1 */
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 4u && rows == 3u && origin_col == 1u && origin_row == 1u && has_clips);
    /* Folded (0.9): logical pads 4-6 and 12 hold rows 0-1; pads 0-2 hold row 2. */
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 4u) == 9u);
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 5u) == 10u);
    assert(velocity[10u] == 0u); /* internal gaps stay black instead of compacting */
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 6u) == 11u);
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 12u) == 17u);
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 0u) == 25u);
}

static void test_viewport_with_one_row_uses_one_pad_row(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips;
    assert(smk_apc40_feedback_set(velocity, g_channel, 35u, 0u, 70u));
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 8u && rows == 1u && origin_col == 3u && origin_row == 4u && has_clips);
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 0u) == 35u);
    assert(smk_apc40_note_for_pad(cols, rows, origin_col, origin_row, 8u) == SMK_APC40_INVALID_NOTE);
}

static void test_viewport_clamp_can_always_return(void)
{
    int16_t offset = 0;
    assert(!smk_apc40_can_scroll(offset, 1, 0u));
    assert(smk_apc40_can_scroll(offset, 1, 1u));
    offset = smk_apc40_scroll_after_move(offset, 1);
    assert(offset == 1);
    assert(!smk_apc40_can_scroll(offset, 1, 0u));
    assert(smk_apc40_can_scroll(offset, -1, 0u));
    offset = smk_apc40_scroll_after_move(offset, -1);
    assert(offset == 0);
    assert(!smk_apc40_can_scroll(offset, -1, 0u));
}

static void test_physical_pad_rows_are_flipped_only(void)
{
    uint8_t pad;
    for (pad = 0u; pad < SMK_APC40_PAD_COUNT; pad++) {
        uint8_t flipped = (uint8_t)(pad ^ SMK_APC40_PAD_ROW_SIZE);
        assert(smk_apc40_logical_pad_for_physical(pad) == flipped);
        assert(smk_apc40_physical_pad_for_logical(pad) == flipped);
        assert(smk_apc40_physical_pad_for_logical(smk_apc40_logical_pad_for_physical(pad)) == pad);
    }
    assert(smk_apc40_logical_pad_for_physical(16u) == SMK_APC40_INVALID_NOTE);
}

static void test_transport_button_notes_and_feedback_states(void)
{
    uint8_t sent = 0u;
    assert(smk_apc40_transport_event(&sent, 0u, 1u) == SMK_APC40_BUTTON_IGNORED);
    assert(!sent);
    assert(smk_apc40_transport_event(&sent, 1u, 1u) == SMK_APC40_BUTTON_ON);
    assert(sent);
    assert(smk_apc40_transport_event(&sent, 1u, 1u) == SMK_APC40_BUTTON_CONSUMED);
    assert(smk_apc40_transport_event(&sent, 0u, 0u) == SMK_APC40_BUTTON_OFF);
    assert(!sent);
    assert(smk_apc40_transport_event(&sent, 0u, 0u) == SMK_APC40_BUTTON_IGNORED);
    assert(smk_apc40_transport_note(0u) == SMK_APC40_PLAY_NOTE);
    assert(smk_apc40_transport_note(1u) == SMK_APC40_RECORD_NOTE);
    assert(smk_apc40_transport_feedback_note(SMK_APC40_PLAY_NOTE));
    assert(smk_apc40_transport_feedback_note(SMK_APC40_RECORD_NOTE));
    assert(!smk_apc40_transport_feedback_note(0x5Cu));
    assert(smk_apc40_transport_feedback_on(127u));
    assert(!smk_apc40_transport_feedback_on(0u));
}

static void test_eight_by_four_uses_exactly_two_views(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips, pad, view;
    for (pad = 0u; pad < 32u; pad++)
        assert(smk_apc40_feedback_set(velocity, g_channel, pad, 0u, 5u));
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 8u && rows == 4u && origin_row == 0u);
    assert(smk_apc40_view_count(cols, rows) == 2u);
    /* View 0 = rows 0-1, view 1 = rows 2-3. No view overlaps or shows an extra row. */
    for (pad = 0u; pad < 16u; pad++) {
        assert(smk_apc40_note_for_pad_view(cols, rows, 0u, 0u, 0u, pad) == pad);
        assert(smk_apc40_note_for_pad_view(cols, rows, 0u, 0u, 1u, pad) == (uint8_t)(16u + pad));
    }
    /* Navigation is clamped to the two views. */
    view = smk_apc40_view_after_move(cols, rows, 0u, -1);
    assert(view == 0u);
    view = smk_apc40_view_after_move(cols, rows, view, 1);
    assert(view == 1u);
    view = smk_apc40_view_after_move(cols, rows, view, 1);
    assert(view == 1u);
    /* 8x2 and 8x1 use one view. 8x5 uses three views; the last is clamped to rows 3-4. */
    assert(smk_apc40_view_count(8u, 2u) == 1u && smk_apc40_view_count(8u, 1u) == 1u);
    assert(smk_apc40_view_count(8u, 5u) == 3u && smk_apc40_view_row_start(8u, 5u, 2u) == 3u);
    assert(smk_apc40_view_count(8u, 3u) == 2u && smk_apc40_view_row_start(8u, 3u, 1u) == 1u);
}

static void test_four_by_four_first_half_on_pads_1_4_and_9_12(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips, row, col, phys;
    for (row = 0u; row < 4u; row++)
        for (col = 0u; col < 4u; col++)
            assert(smk_apc40_feedback_set(velocity, g_channel, (uint8_t)(row * 8u + col), 0u, 9u));
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 4u && rows == 4u && smk_apc40_view_count(cols, rows) == 1u);
    for (phys = 0u; phys < 16u; phys++) {
        uint8_t logical = smk_apc40_logical_pad_for_physical(phys);
        uint8_t note = smk_apc40_note_for_pad_view(cols, rows, origin_col, origin_row, 0u, logical);
        uint8_t source_row = (uint8_t)(note / 8u);
        assert(note != SMK_APC40_INVALID_NOTE && note % 8u == phys % 4u);
        if (phys % 8u < 4u)   /* pads 1-4 and 9-12: second half (rows 2-3) */
            assert(source_row >= 2u);
        else                  /* pads 5-8 and 13-16: first half (rows 0-1) */
            assert(source_row <= 1u);
    }
    /* A 4x4 project with an empty outer column still folds. */
    for (row = 0u; row < 4u; row++)
        velocity[row * 8u + 3u] = 0u;
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 4u && rows == 4u);
}

static void test_transport_led_lights_on_press(void)
{
    uint8_t led = 0u;
    led = smk_apc40_transport_led_after_press(led);
    assert(led == 1u);
    led = smk_apc40_transport_led_after_press(led);
    assert(led == 0u);
}

static void test_page_change_snapshot_clears_old_page(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0}, channel[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t cols, rows, origin_col, origin_row, has_clips, count = 0u, note, phys;
    uint64_t mask = 0u;
    /* Old page: an 8x4 grid of clips. */
    for (note = 0u; note < 32u; note++)
        velocity[note] = 5u;
    /* New page: Loopy sends only the 16 clips of a 4x4 grid, and no "off" notes. */
    for (note = 0u; note < 32u; note++)
        if (note % 8u < 4u) {
            smk_apc40_feedback_set(velocity, channel, note, 0u, 21u);
            smk_apc40_burst_touch(&mask, &count, note);
        }
    assert(count == 16u);
    assert(smk_apc40_burst_finish(velocity, channel, &mask, &count) == 1u);
    assert(mask == 0u && count == 0u);
    for (note = 0u; note < SMK_APC40_CLIP_COUNT; note++)
        assert((velocity[note] != 0u) == (note < 32u && note % 8u < 4u));
    /* The 4x4 now fills all 16 pads in one view. */
    smk_apc40_build_layout(velocity, &cols, &rows, &origin_col, &origin_row, &has_clips);
    assert(cols == 4u && rows == 4u && smk_apc40_view_count(cols, rows) == 1u);
    for (phys = 0u; phys < 16u; phys++) {
        uint8_t n = smk_apc40_note_for_pad_view(cols, rows, origin_col, origin_row, 0u,
                                                smk_apc40_logical_pad_for_physical(phys));
        assert(n != SMK_APC40_INVALID_NOTE && velocity[n] != 0u);
    }
}

static void test_small_burst_keeps_other_clips(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0}, channel[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t count = 0u, note;
    uint64_t mask = 0u;
    for (note = 0u; note < 32u; note++)
        velocity[note] = 5u;
    /* A cue or play change of 3 clips is not a page change. */
    for (note = 0u; note < 3u; note++) {
        smk_apc40_feedback_set(velocity, channel, note, 9u, 21u);
        smk_apc40_burst_touch(&mask, &count, note);
    }
    smk_apc40_burst_touch(&mask, &count, 1u);   /* repeated cell counts once */
    assert(count == 3u);
    assert(smk_apc40_burst_finish(velocity, channel, &mask, &count) == 0u);
    for (note = 0u; note < 32u; note++)
        assert(velocity[note] != 0u);
}

static void test_play_led_blinks_with_clock(void)
{
    uint32_t tick, on = 0u;
    assert(smk_apc40_play_led(0u, 1u, 0u) == 0u);
    assert(smk_apc40_play_led(1u, 0u, 13u) == 1u);   /* lit on press, no clock yet */
    for (tick = 0u; tick < 96u; tick++)               /* 4 beats */
        on += smk_apc40_play_led(1u, 1u, tick);
    assert(on == 24u);                                /* 6 ticks lit per beat */
    assert(smk_apc40_play_led(1u, 1u, 0u) && smk_apc40_play_led(1u, 1u, 24u));
    assert(!smk_apc40_play_led(1u, 1u, 12u));
}

static void test_partial_latch_grows_to_full_four_by_four(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t c0, r0, oc0, or0, c1, r1, oc1, or1, has, row, col, phys;
    /* The latch saw only rows 0-1 of a 4x4 grid: an 8-wide 2-row layout. */
    for (row = 0u; row < 2u; row++)
        for (col = 0u; col < 4u; col++)
            velocity[row * 8u + col] = 9u;
    smk_apc40_build_layout(velocity, &c0, &r0, &oc0, &or0, &has);
    assert(c0 == 8u && r0 == 2u);
    /* Rows 2-3 arrive later. The layout grows and folds to one 4x4 view. */
    for (row = 2u; row < 4u; row++)
        for (col = 0u; col < 4u; col++)
            velocity[row * 8u + col] = 9u;
    smk_apc40_build_layout(velocity, &c1, &r1, &oc1, &or1, &has);
    assert(c1 == 4u && r1 == 4u);
    assert(smk_apc40_layout_grows(c0, r0, oc0, or0, c1, r1, oc1, or1));
    for (phys = 0u; phys < 16u; phys++)
        assert(velocity[smk_apc40_note_for_pad_view(c1, r1, oc1, or1, 0u,
                        smk_apc40_logical_pad_for_physical(phys))] != 0u);
    /* A clip LED turning off cannot shrink the layout. */
    assert(!smk_apc40_layout_grows(c1, r1, oc1, or1, 4u, 3u, 0u, 0u));
    assert(!smk_apc40_layout_grows(c1, r1, oc1, or1, c1, r1, oc1, or1));
    /* A 4x4 whose last row is still empty (late feedback) folds as in 0.9. */
    velocity[24] = velocity[25] = velocity[26] = velocity[27] = 0u;
    smk_apc40_build_layout(velocity, &c1, &r1, &oc1, &or1, &has);
    assert(c1 == 4u && r1 == 3u && smk_apc40_view_count(c1, r1) == 1u);
    /* 8-wide layouts never grow after the latch (0.7 behavior). */
    assert(!smk_apc40_layout_grows(8u, 2u, 0u, 0u, 8u, 4u, 0u, 0u));
}

static void test_pending_clips_blink_static_clips_steady(void)
{
    uint8_t ch;
    /* Only blinking channels 11-15 (queued) blink. Static, one-shot and pulsing
     * (playing) states stay steady, so not all pads blink on clip mode entry. */
    for (ch = 11u; ch <= 15u; ch++) {
        assert(smk_apc40_is_queued(ch));
        assert(smk_apc40_brightness(ch, 0u, 0u) == 255u);
        assert(smk_apc40_brightness(ch, 200u, 0u) == 0u);
    }
    for (ch = 0u; ch < 11u; ch++) {
        assert(!smk_apc40_is_queued(ch));
        assert(smk_apc40_brightness(ch, 200u, 1u) == 255u);
    }
    /* One blink per beat: 24 ticks of 24 PPQN clock. */
    assert(SMK_APC40_QUEUED_BLINK_TICKS == 24u);
    /* Protocol rates: 1/24 note is 4 ticks, not 1 tick (the old 1-tick table blinked too fast). */
    assert(smk_apc40_animation_clock_period(11u) == 4u);
    assert(smk_apc40_animation_clock_period(14u) == 24u);
}

static void test_scene_launch_and_cue_bursts_keep_other_clips(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0}, channel[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t count = 0u, note;
    uint64_t mask = 0u;
    for (note = 0u; note < 16u; note++)
        velocity[note] = 5u;                  /* an 8x2 page with 16 clips */
    /* Cue burst: 8 clips of row 0 go to a blink state. Not a page change. */
    for (note = 0u; note < 8u; note++) {
        smk_apc40_feedback_set(velocity, channel, note, 14u, 21u);
        smk_apc40_burst_touch(&mask, &count, note);
    }
    assert(smk_apc40_burst_finish(velocity, channel, &mask, &count) == 0u);
    for (note = 0u; note < 16u; note++)
        assert(velocity[note] != 0u);
    /* 32-clip page: a scene launch plays 8 clips. 8 of 32 is less than half. */
    for (note = 0u; note < 32u; note++)
        velocity[note] = 5u, channel[note] = 0u;
    for (note = 0u; note < 8u; note++) {
        smk_apc40_feedback_set(velocity, channel, note, 0u, 21u);
        smk_apc40_burst_touch(&mask, &count, note);
    }
    assert(smk_apc40_burst_finish(velocity, channel, &mask, &count) == 0u);
    for (note = 0u; note < 32u; note++)
        assert(velocity[note] != 0u);
}

static void test_row_launch_on_small_page_keeps_clips(void)
{
    uint8_t velocity[SMK_APC40_CLIP_COUNT] = {0}, channel[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t count = 0u, note;
    uint64_t mask = 0u;
    for (note = 0u; note < 16u; note++)
        velocity[note] = 5u;                  /* 8x2 page, 16 clips */
    for (note = 0u; note < 8u; note++) {      /* row 0 starts: 8 static cells, half of lit */
        smk_apc40_feedback_set(velocity, channel, note, 0u, 21u);
        smk_apc40_burst_touch(&mask, &count, note);
    }
    assert(smk_apc40_burst_finish(velocity, channel, &mask, &count) == 0u);
    for (note = 0u; note < 16u; note++)
        assert(velocity[note] != 0u);
}

/* Replay of captured Loopy output (2026-10-15): a refresh sends note off for all 40
 * clip notes, then all colors (0 for unused cells) 4 ms later. */
static void test_loopy_refresh_keeps_last_colors(void)
{
    uint8_t vel[SMK_APC40_CLIP_COUNT] = {0}, ch[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t flags[SMK_APC40_CLIP_COUNT] = {0}, tick[SMK_APC40_CLIP_COUNT] = {0};
    static const uint8_t cap[8] = {0x0B, 0x0B, 0x0F, 0x0F, 0x13, 0x13, 0x37, 0x37};
    uint8_t n;
    uint32_t ms;
    for (n = 8u; n < 40u; n++)
        vel[n] = 0x27u;                               /* stale colors of the old page */
    vel[3] = 0x1Fu;
    for (n = 0u; n < 40u; n++)
        smk_apc40_cell_event(vel, ch, flags, tick, n, 0u, 0u, (uint8_t)(1000u >> 4));
    for (n = 0u; n < 40u; n++)
        smk_apc40_cell_event(vel, ch, flags, tick, n, 0u, n < 8u ? 0u : cap[n % 8u],
                             (uint8_t)(1004u >> 4));
    for (ms = 1010u; ms < 6000u; ms += 16u) {
        smk_apc40_cells_age(vel, ch, flags, tick, (uint8_t)(ms >> 4));
        for (n = 0u; n < 40u; n++) {
            assert(vel[n] == (n < 8u ? 0u : cap[n % 8u]));  /* never dies, no stale cell */
            assert(!(flags[n] & SMK_APC40_CELL_QUEUED));    /* a refresh is not a flash */
        }
    }
}

/* Captured flash of a queued clip: note 0x20 color 0x39, then 0, every ~100 ms. */
static void test_loopy_flash_is_held_and_blinks_on_beat(void)
{
    uint8_t vel[SMK_APC40_CLIP_COUNT] = {0}, ch[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t flags[SMK_APC40_CLIP_COUNT] = {0}, tick[SMK_APC40_CLIP_COUNT] = {0};
    uint32_t ms;
    smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, 0x37u, 0u);
    for (ms = 1920u; ms < 3200u; ms += 100u) {
        uint8_t on = (uint8_t)(((ms - 1920u) / 100u) % 2u == 0u);
        smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, on ? 0x39u : 0u, (uint8_t)(ms >> 4));
        smk_apc40_cells_age(vel, ch, flags, tick, (uint8_t)((ms + 50u) >> 4));
        if (ms >= 2320u)                             /* after two toggles */
            assert(vel[0x20] == 0x39u && (flags[0x20] & SMK_APC40_CELL_QUEUED));
    }
    /* Clip starts: steady color, no more flash. Queued state ends, color stays. */
    smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, 0x39u, (uint8_t)(3226u >> 4));
    smk_apc40_cells_age(vel, ch, flags, tick, (uint8_t)(3700u >> 4));
    assert(vel[0x20] == 0x39u && !(flags[0x20] & SMK_APC40_CELL_QUEUED));
    /* A plain off clears the cell at once. */
    smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, 0u, (uint8_t)(4000u >> 4));
    assert(vel[0x20] == 0u);
    /* A flash that ends on off clears the cell after the queued state ends. */
    for (ms = 5000u; ms < 5500u; ms += 100u)
        smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u,
                             ((ms - 5000u) / 100u) % 2u == 0u ? 0x39u : 0u, (uint8_t)(ms >> 4));
    smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, 0u, (uint8_t)(5500u >> 4));
    assert(vel[0x20] == 0x39u);
    smk_apc40_cells_age(vel, ch, flags, tick, (uint8_t)(6000u >> 4));
    assert(vel[0x20] == 0u && !(flags[0x20] & SMK_APC40_CELL_QUEUED));
}

/* Blink period against MIDI Clock: one cycle per 24 ticks, 12 on and 12 off. */
static void test_blink_period_is_one_beat(void)
{
    uint32_t t, on = 0u, edges = 0u;
    uint8_t prev = smk_apc40_beat_phase(0u) < 128u;
    for (t = 0u; t < 24u * 8u; t++) {
        uint8_t lit = smk_apc40_beat_phase(t) < 128u;
        on += lit;
        if (lit && !prev)
            edges++;
        prev = lit;
    }
    assert(on == 12u * 8u);
    assert(edges == 7u);                           /* 8 beats: 7 rising edges after tick 0 */
    assert(smk_apc40_beat_phase(0u) < 128u && smk_apc40_beat_phase(24u) < 128u);
    assert(smk_apc40_beat_phase(12u) >= 128u);
}

static void test_lcd_map_fits_used_area(void)
{
    smk_apc40_lcd_map_t m;
    m = smk_apc40_lcd_map(8u, 2u, 0u, 0u, 0u, 240u, 138u);          /* no clips: full 8x5 */
    assert(m.ncols == 8u && m.nrows == 5u && m.pitch == 26u);
    m = smk_apc40_lcd_map(4u, 4u, 0u, 1u, 1u, 240u, 138u);          /* 4x4: bigger cells */
    assert(m.col0 == 0u && m.row0 == 1u && m.ncols == 4u && m.nrows == 4u && m.pitch == 33u);
    assert(m.x0 >= 0 && m.x0 + 4 * 33 <= 240 && m.y0 >= 0 && m.y0 + 4 * 33 <= 138);
    /* Screen row = nrows - 1 - (source row - row0): the highest APC row (the top
     * Loopy row) is on top, for 4x4 and 8-wide alike. The 4x4 pad fold is not used. */
    assert(smk_apc40_lcd_screen_row(&m, 4u) == 0u && smk_apc40_lcd_screen_row(&m, 1u) == 3u);
    m = smk_apc40_lcd_map(8u, 4u, 0u, 1u, 1u, 240u, 138u);          /* 8x4 */
    assert(smk_apc40_lcd_screen_row(&m, 4u) == 0u && smk_apc40_lcd_screen_row(&m, 1u) == 3u);
    assert(m.ncols == 8u && m.nrows == 4u && m.pitch == 29u);
    m = smk_apc40_lcd_map(3u, 2u, 2u, 3u, 1u, 240u, 138u);          /* small area: big cells */
    assert(m.col0 == 2u && m.row0 == 3u && m.ncols == 3u && m.nrows == 2u && m.pitch == 67u);
}

static void test_loopy_history_packets(void)
{
    /* USB-MIDI: CIN 9, 9F 70 7F (undo on); CIN 8, 8F 70 00 (off); 9F 71 7F (redo on). */
    assert(smk_apc40_history_packet(0u, 1u) == (0x09u | 0x9Fu << 8 | 0x70u << 16 | 0x7Fu << 24));
    assert(smk_apc40_history_packet(0u, 0u) == (0x08u | 0x8Fu << 8 | 0x70u << 16));
    assert(smk_apc40_history_packet(1u, 1u) == (0x09u | 0x9Fu << 8 | 0x71u << 16 | 0x7Fu << 24));
    assert(smk_apc40_history_packet(1u, 0u) == (0x08u | 0x8Fu << 8 | 0x71u << 16));
    /* Not an APC40 mkII note: above the clip notes and the APC button range (0x30-0x66). */
    assert(SMK_APC40_UNDO_NOTE > 0x66u && SMK_APC40_REDO_NOTE > 0x66u);
}

/* Bug a67: the first blinks of a queued clip followed the Loopy 100 ms flash. Model of
 * main_fm1.c smk_pads and smk_apc_led_brightness: with clock, half a beat on and half off
 * (phase from the clock count); with no clock, 250 ms on and 250 ms off. Return the time
 * between the first two dark-to-lit edges after the flash starts at 1000 ms. */
static uint32_t first_pending_blink_period(uint32_t bpm)
{
    uint8_t vel[SMK_APC40_CLIP_COUNT] = {0}, ch[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t flags[SMK_APC40_CLIP_COUNT] = {0}, tick[SMK_APC40_CLIP_COUNT] = {0};
    uint8_t prev = 1u, last16 = 0u, lit;
    uint32_t ms, edge[2] = {0u, 0u}, edges = 0u;
    smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u, 0x37u, 0u);   /* idle clip */
    for (ms = 1u; ms < 4000u && edges < 2u; ms++) {
        if (ms >= 1000u && ms < 3500u && (ms - 1000u) % 100u == 0u)    /* Loopy flash */
            smk_apc40_cell_event(vel, ch, flags, tick, 0x20u, 0u,
                                 ((ms - 1000u) / 100u) % 2u ? 0u : 0x39u, (uint8_t)(ms >> 4));
        if ((uint8_t)(ms >> 4) != last16) {                            /* smk_apc_usb_tick */
            last16 = (uint8_t)(ms >> 4);
            smk_apc40_cells_age(vel, ch, flags, tick, last16);
        }
        lit = vel[0x20] != 0u;
        if (lit && ((flags[0x20] & SMK_APC40_CELL_QUEUED) || smk_apc40_is_queued(ch[0x20])))
            lit = bpm ? smk_apc40_beat_phase(ms * bpm * 24u / 60000u) < 128u : !((ms / 250u) & 1u);
        if (ms >= 1000u && lit && !prev)
            edge[edges++] = ms;
        prev = lit;
    }
    assert(edges == 2u);
    return edge[1] - edge[0];
}

static void test_first_pending_blink_has_beat_period(void)
{
    uint32_t p;
    p = first_pending_blink_period(120u);
    assert(p >= 498u && p <= 502u);             /* 120 BPM: 500 ms, not 200 ms */
    p = first_pending_blink_period(90u);
    assert(p >= 664u && p <= 669u);             /* 90 BPM: 667 ms */
    p = first_pending_blink_period(0u);
    assert(p == 500u);                          /* no clock: the 250/250 ms default */
}

/* a74 (MID-14): ui.c input() for PLAY on the SMK-37 (the PLAY note: channel 16, as Undo / Redo). The clip mode handler first (it uses the event in clip
 * mode), then the PLAY note outside clip mode, which does not use the event (PLAY starts or stops X0X). */
static uint32_t play_out[8];
static int play_nout, play_taps;
static void play_button(uint8_t *clip_sent, uint8_t *note_sent, uint8_t clip_mode, uint8_t home, uint8_t pressed)
{
    uint8_t ev = smk_apc40_transport_event(clip_sent, clip_mode, pressed);   /* smk_clip_transport_button */
    if (ev != SMK_APC40_BUTTON_IGNORED) {
        if (ev == SMK_APC40_BUTTON_ON || ev == SMK_APC40_BUTTON_OFF)
            play_out[play_nout++] = (ev == SMK_APC40_BUTTON_ON ? 0x09u | 0x90u << 8 | 0x5Bu << 16 | 0x7Fu << 24
                                                                : 0x08u | 0x80u << 8 | 0x5Bu << 16 | 0x7Fu << 24);
        return;                                                              /* used: X0X does not start */
    }
    ev = smk_apc40_play_note_event(note_sent, clip_mode, home, pressed);     /* smk_play_note_button */
    if (ev == SMK_APC40_BUTTON_ON || ev == SMK_APC40_BUTTON_OFF)
        play_out[play_nout++] = smk_apc40_play_note_packet(ev == SMK_APC40_BUTTON_ON);
    if (pressed && !home)
        play_taps++;                                                         /* button_tap(B_PLAY): start or stop */
}
static void test_play_note_outside_clip_mode(void)
{
    uint8_t cs = 0u, ns = 0u;
    const uint32_t on = 0x09u | 0x9Fu << 8 | 0x5Bu << 16 | 0x7Fu << 24, off = 0x08u | 0x8Fu << 8 | 0x5Bu << 16;   /* channel 16 */
    assert(smk_apc40_play_note_packet(1u) == on);
    assert(smk_apc40_play_note_packet(0u) == off);
    play_nout = play_taps = 0;                    /* outside clip mode: note on, note off, and X0X starts */
    play_button(&cs, &ns, 0u, 0u, 1u);
    assert(play_nout == 1 && play_out[0] == on && play_taps == 1);
    play_button(&cs, &ns, 0u, 0u, 0u);
    assert(play_nout == 2 && play_out[1] == off && play_taps == 1);
    play_button(&cs, &ns, 0u, 0u, 1u);            /* the second press: X0X stops, the note again */
    play_button(&cs, &ns, 0u, 0u, 0u);
    assert(play_nout == 4 && play_out[2] == on && play_out[3] == off && play_taps == 2);
    play_nout = play_taps = 0;                    /* clip mode: one APC PLAY note on and off, X0X does not start */
    play_button(&cs, &ns, 1u, 0u, 1u);
    play_button(&cs, &ns, 1u, 0u, 0u);
    assert(play_nout == 2 && play_out[0] == (0x09u | 0x90u << 8 | 0x5Bu << 16 | 0x7Fu << 24) &&
           (play_out[1] & 0xFFFFFFu) == (0x08u | 0x80u << 8 | 0x5Bu << 16));   /* the APC PLAY: channel 1 */
    assert(play_taps == 0 && !ns && !cs);
    play_nout = play_taps = 0;                    /* HOME + PLAY (X0X redo): no note */
    play_button(&cs, &ns, 0u, 1u, 1u);
    play_button(&cs, &ns, 0u, 1u, 0u);
    assert(play_nout == 0 && play_taps == 0);
    play_nout = 0;                                /* pressed outside, clip mode starts, released: one note off */
    play_button(&cs, &ns, 0u, 0u, 1u);
    play_button(&cs, &ns, 1u, 0u, 0u);
    assert(play_nout == 2 && play_out[0] == on && play_out[1] == off && !ns && !cs);
    play_nout = 0;                                /* pressed in clip mode, clip mode ends, released: the APC off only */
    play_button(&cs, &ns, 1u, 0u, 1u);
    play_button(&cs, &ns, 0u, 0u, 0u);
    assert(play_nout == 2 && (play_out[1] & 0xFFFFFFu) == (0x08u | 0x80u << 8 | 0x5Bu << 16) && !ns && !cs);
}

int main(void)
{
    test_play_note_outside_clip_mode();
    test_first_pending_blink_has_beat_period();
    test_loopy_history_packets();
    test_lcd_map_fits_used_area();
    test_loopy_refresh_keeps_last_colors();
    test_loopy_flash_is_held_and_blinks_on_beat();
    test_blink_period_is_one_beat();
    test_row_launch_on_small_page_keeps_clips();
    test_scene_launch_and_cue_bursts_keep_other_clips();
    test_partial_latch_grows_to_full_four_by_four();
    test_pending_clips_blink_static_clips_steady();
    test_play_led_blinks_with_clock();
    test_page_change_snapshot_clears_old_page();
    test_small_burst_keeps_other_clips();
    test_eight_by_four_uses_exactly_two_views();
    test_four_by_four_first_half_on_pads_1_4_and_9_12();
    test_transport_led_lights_on_press();
    test_eight_by_four_crops_viewport_margin();
    test_four_by_four_folds_into_one_eight_by_two_grid();
    test_sparse_eight_wide_cells_keep_relative_gaps();
    test_viewport_with_one_row_uses_one_pad_row();
    test_viewport_clamp_can_always_return();
    test_physical_pad_rows_are_flipped_only();
    test_transport_button_notes_and_feedback_states();
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X drum part: the 9W9 TR-909 engine (Charles Vestal, GPL-3.0; itself grown out
 * of ER-99 by Matthew Cieplak, GPL-3.0), ported to the FM-1.
 *
 * Circuit-modelled BD, SD, LT/MT/HT, RS, CP; sampled CH/OH (one buffer, choking
 * each other), CR, RD (IMA ADPCM in flash, decoded as they play) -- the same models, pot tables and defaults as 9W9. The
 * send reverb / delay and the master stage live in fxbus.{h,c}.
 *
 * Mono, 44.1 kHz, float, no libm, no allocation. Idle voices cost nothing:
 * every voice has 9W9's mute countdown, and the block loop runs a voice only for
 * the samples it is still sounding.
 *
 * Threading: drum909_trigger / drum909_set are called between render blocks
 * (the same thread, or with the audio ISR held off); none of them loops over
 * more than a few dozen operations. */
#pragma once
#include <stdint.h>
#include "x0x_param.h"
#include "drum909_dsp.h"

enum { DR_BD, DR_SD, DR_LT, DR_MT, DR_HT, DR_RS, DR_CP, DR_CH, DR_OH, DR_CR, DR_RD, DR_NUM, DR_KIT = DR_NUM };

#define DR_MAX_PARAMS 11         /* most params any voice (or the kit) has (X0X: + PAN, the SD's DECAY, the BD's sends) */
#define DR_NZ_HIST 256           /* noise history kept across blocks (filter warm-up) */
#define DR_NZ_BUF (DR_NZ_HIST + 2 * 256)

/* BD and SD: 9W9's er99_bt_t */
typedef struct {
    /* panel values (engineering units) */
    float tune, sweep_depth, sweep_time, decay, attack, click_tone, level;
    float tune2, osc2_mix, snappy, noise_decay, noise_hp, amp_hold, pitch_mod;
    float drive;
    int32_t dist_type;
    d9_shape_t shape;
    /* runtime */
    uint32_t ph, ph2;
    d9_env_t pitch, amp, click_env, noise_env;
    d9_biquad_t click_lp, noise_hpf, noise_lpf, dc_block;
    int32_t noise_hold, noise_gated, amp_hold_left, bd_phold, impulse, mute;
    int32_t click_stale, click_warm;   /* skipped click filter: see d9_render_bd */
    float bd_df, bd_mult, bd_base, out_gain;
    float crush_st[2];
} d9_bt_t;

/* LT/MT/HT: 9W9's er99_tom_t (three VCOs); reads the panel from a d9_bt_t */
typedef struct {
    uint32_t ph[3];
    d9_env_t env[3], pitch, noise_env;
    d9_biquad_t noise_bp, dc_block;
    float out_gain, noise_level;
    float crush_st[2];
    int32_t mute;
    int32_t stick_stale, stick_warm;   /* skipped stick filter: see d9_render_tom */
} d9_tom_t;

typedef struct {
    float tune, tune2, res, decay, noise_mix, drive, level, accent;
    int32_t dist_type;
    d9_shape_t shape;
    d9_biquad_t bp1, bp2, hp;
    d9_env_t amp;
    float crush_st[2];
    int32_t impulse, mute;
} d9_rim_t;

typedef struct {
    float tune, res, spread, burst_decay, tail_decay, tail_level, drive, level, accent;
    int32_t dist_type;
    d9_shape_t shape;
    d9_biquad_t bp, hp;
    d9_env_t burst, tail;
    float crush_st[2];
    float next_pulse;
    int32_t pulse_index, mute;
} d9_clap_t;

typedef struct {
    float decay, volume, pitch, drive;
    int32_t dist_type;
    d9_shape_t shape;
    const uint8_t *adpcm;         /* IMA ADPCM, 44.1 kHz (ima_adpcm.h) */
    uint32_t len;                 /* samples */
    uint32_t dk;                  /* samples decoded so far; h0, h1 = samples dk - 2, dk - 1 */
    int32_t pred, idx;            /* decoder state after dk samples */
    int32_t h0, h1;
    uint32_t pos, frac;           /* 32.32 read position */
    uint32_t inc, incf;           /* 32.32 playback rate */
    int32_t playing;              /* pos is valid (9W9: pos >= 0) */
    d9_env_t out;
    float crush_st[2];
    int32_t mute;
} d9_smp_t;

struct drum909 {
    d9_bt_t bt[5];                /* BD SD LT MT HT panels; BD and SD voices */
    d9_tom_t tom[3];              /* LT MT HT voices */
    d9_rim_t rim;
    d9_clap_t clap;
    d9_smp_t smp[4];              /* CH OH CR RD */
    float send_rev[DR_NUM], send_dly[DR_NUM];
    float pan_l[DR_NUM], pan_r[DR_NUM];   /* X0X: each voice's pan (x0x_pan_gains) */
    float pan_lc[DR_NUM], pan_rc[DR_NUM]; /* where each voice's pan gains are now, gliding to pan_l/r */
    float pan_dl[DR_NUM], pan_dr[DR_NUM]; /* this block's glide per sample */
    float accent, vel_depth;      /* kit */
    uint32_t noise;
    float nz_buf[DR_NZ_BUF];      /* noise, linear; the block plus >= DR_NZ_HIST before it */
    int32_t nz_pos;               /* where the next block's noise starts */
    uint8_t pots[DR_NUM + 1][DR_MAX_PARAMS];
};
typedef struct drum909 drum909_t;

void drum909_init(drum909_t *d);
void drum909_trigger(drum909_t *d, int voice, float vel);
void drum909_render(drum909_t *d, float *dry, float *rev, float *dly, int n);
/* X0X stereo: each voice placed by its PAN into dry_l / dry_r (sends mono); all centred, both are
 * drum909_render's dry exactly */
void drum909_render_st(drum909_t *d, float *dry_l, float *dry_r, float *rev, float *dly, int n);
/* Only selected tracks reach dry/send buses; every voice still advances normally. */
void drum909_render_st_masked(drum909_t *d, float *dry_l, float *dry_r, float *rev, float *dly,
                             int n, uint16_t audible_tracks);
void drum909_pan_settle(drum909_t *d);   /* every pan to its target at once (the kit is silent: no zipper) */
int drum909_nparams(int voice);
const x0x_param_t *drum909_param(int voice, int i);
void drum909_set(drum909_t *d, int voice, int i, int value);
int drum909_get(const drum909_t *d, int voice, int i);

/* true while any voice is still sounding (for a caller that wants to skip work) */
int drum909_active(const drum909_t *d);

/* SPDX-License-Identifier: GPL-3.0-only */
/* Linked production-C regression: render-chunk invariance of the scheduled MIDI
 * clock, local gestures and 303 NoteOff. No device or target firmware is run.
 * The test drives seq_until_event exactly as the documented engine render loop. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sequencer.h"

#define NEVENTS 256
#define CHECK(x) do { ++checks; if (!(x)) { ++failures; \
    fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #x); } } while (0)

typedef struct { uint32_t at; uint8_t st, note, vel; } event_t;
typedef struct { event_t event[NEVENTS]; unsigned len; } trace_t;
typedef struct { trace_t trace; uint32_t now; unsigned chunks, limit; } observer_t;
static pattern_t patterns[NPAT];
static int checks, failures;

static void midi_out(void *p, uint8_t st, uint8_t d1, uint8_t d2)
{
    observer_t *o = p;
    if (o->trace.len >= NEVENTS) { ++failures; return; }
    o->trace.event[o->trace.len++] = (event_t){o->now, st, d1, d2};
}
static int bass_on(void *ctx, int part, int note, int accent, int slide, int velocity)
{
    (void)ctx; (void)part; (void)note; (void)accent; (void)slide; (void)velocity;
 return 1; }
static void bass_off(void *ctx, int part) { (void)ctx; (void)part; }
static int drum(void *ctx, int kit, int voice, float vel)
{ (void)ctx; (void)kit; (void)voice; (void)vel; return 1; }
static unsigned count_status(const observer_t *o, uint8_t st, int note)
{
    unsigned n = 0;
    for (unsigned i = 0; i < o->trace.len; i++)
        if (o->trace.event[i].st == st && (note < 0 || o->trace.event[i].note == note))
            n++;
    return n;
}
static void init(seq_t *s, observer_t *o, unsigned limit)
{
    for (unsigned i = 0; i < NPAT; ++i)
        pattern_init(&patterns[i], 100 + i, 200 + i);
    patterns[0].bass[0].step[0] = (bstep_t){60, G_NOTE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){64, G_NOTE, 100};
    seq_init(s, patterns);
    s->send_notes = s->send_clock = 1;
    *o = (observer_t){0};
    o->limit = limit;
}
static seq_sink_t sink(observer_t *o)
{
    seq_sink_t s = {0};
    s.ctx = o;
    s.midi = midi_out;
    s.drum = drum;
    s.bass_on = bass_on;
    s.bass_off = bass_off;
    return s;
}
static void advance(seq_t *s, observer_t *o, seq_sink_t *out, uint32_t k)
{
    o->now += k;
    seq_advance(s, k, out);
}
/* This is the actual firmware scheduling contract: render at most the next due
 * event, then let the sequencer advance. A test that calls seq_advance once per
 * arbitrary 1024-frame chunk would miss sample-accurate timing regressions. */
static void render(seq_t *s, observer_t *o, seq_sink_t *out, uint32_t frames)
{
    while (frames) {
        uint32_t avail = frames < o->limit ? frames : o->limit;
        uint32_t k = seq_until_event(s, avail);
        CHECK(k >= 1 && k <= avail);
        if (!k || k > avail) { ++failures; return; }
        advance(s, o, out, k);
        frames -= k;
        o->chunks++;
    }
}
static observer_t scenario(unsigned limit)
{
    seq_t s; observer_t o;
    init(&s, &o, limit);
    seq_sink_t out = sink(&o);
    seq_start(&s);
    /* Start is picked up on the first audio sample. All partitions share it. */
    advance(&s, &o, &out, 1);
    CHECK(s.playing && !s.ext);
    CHECK(count_status(&o, 0xFA, -1) == 1);
    CHECK(count_status(&o, 0x91, 60) == 1);
    /* STOP while step one's 303 gate is held must send exactly one NoteOff. */
    render(&s, &o, &out, 1500);
    seq_stop(&s);
    advance(&s, &o, &out, 1);
    CHECK(!s.playing);
    CHECK(count_status(&o, 0x81, 60) == 1);
    seq_continue(&s);
    advance(&s, &o, &out, 1);
    CHECK(s.playing);
    CHECK(count_status(&o, 0xFB, -1) == 1);
    CHECK(count_status(&o, 0x91, 64) == 1);
    render(&s, &o, &out, 12000);
    seq_stop(&s);
    advance(&s, &o, &out, 1);
    seq_stop(&s); /* redundant release cannot send a second NoteOff */
    advance(&s, &o, &out, 1);
    CHECK(!s.playing);
    CHECK(count_status(&o, 0x81, 60) == 1);
    CHECK(count_status(&o, 0x81, 64) == 1);
    CHECK(count_status(&o, 0x90, -1) == 0);
    CHECK(count_status(&o, 0xFA, -1) == 1);
    CHECK(count_status(&o, 0xFB, -1) == 1);
    CHECK(count_status(&o, 0xFC, -1) == 2);
    CHECK(count_status(&o, 0xF8, -1) >= 10);
    return o;
}
static void compare(const observer_t *base, const observer_t *other)
{
    CHECK(base->trace.len == other->trace.len);
    unsigned n = base->trace.len < other->trace.len ? base->trace.len : other->trace.len;
    for (unsigned i = 0; i < n; ++i) {
        const event_t *a = &base->trace.event[i], *b = &other->trace.event[i];
        CHECK(a->at == b->at);
        CHECK(a->st == b->st);
        CHECK(a->note == b->note);
        CHECK(a->vel == b->vel);
    }
}
int main(void)
{
    const unsigned limits[] = {1, 2, 7, 63, 64, 65, 127, 128, 255, 256, 511, 512, 1024};
    observer_t base = scenario(limits[0]);
    /* 44.1 kHz, 125 BPM -> 882 samples per F8 and 2646 per 303 half-step.
     * Fixed anchor times guard against all partitions drifting identically. */
    static const struct { unsigned index; event_t event; } anchors[] = {
        {0, {1, 0xFA, 0, 0}}, {1, {1, 0x91, 60, 100}},
        {2, {1, 0xF8, 0, 0}}, {3, {883, 0xF8, 0, 0}},
        {4, {1502, 0x81, 60, 0}}, {5, {1502, 0xFC, 0, 0}},
        {6, {1503, 0xFB, 0, 0}}, {7, {1503, 0x91, 64, 100}},
        {9, {2385, 0xF8, 0, 0}}, {11, {4149, 0x81, 64, 0}},
        {22, {12969, 0xF8, 0, 0}}, {23, {13504, 0xFC, 0, 0}}
    };
    CHECK(base.trace.len == 24);
    for (unsigned i = 0; i < sizeof anchors / sizeof anchors[0]; ++i) {
        const event_t *a = &base.trace.event[anchors[i].index];
        const event_t *b = &anchors[i].event;
        CHECK(a->at == b->at && a->st == b->st && a->note == b->note && a->vel == b->vel);
    }
    for (unsigned i = 1; i < sizeof limits / sizeof limits[0]; ++i) {
        observer_t o = scenario(limits[i]);
        compare(&base, &o);
    }
    fprintf(stderr, "seq sample scheduling: %d/%d checks %s; %u events\n",
            checks - failures, checks, failures ? "FAILED" : "PASSED", base.trace.len);
    return failures ? EXIT_FAILURE : EXIT_SUCCESS;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* M-UPGRADE update entry.
 *
 * The updater talks SysEx (F0 pack7(00 59 cmd len24 body chk) F7):
 *   cmd 0x11  handshake -> we answer our package identity (FELUCCA_ID)
 *   F0 22 24 35 7F F7  upgrade -> ota_session(): pull parts of the package
 *     with cmd 0x30 read requests, check them, stage the package's update
 *     loader at 0xE0000 (outside Felucca's store; SMK: 0xBB000), ask 0xE0000000 ("success"),
 *     then write the UPDATA_PARM record (flash 0xE4F00, SMK 0xBFF00, + RAM 0x01C7FD88) and
 *     reset. The SPL runs the loader, which installs the package.
 * Nothing is committed before the host's "success"; any failure erases the
 * staging area and Felucca carries on.
 *
 * The firmware (felucca.c) and the host test supply these hooks:
 *   ota_wire_send(p, n)        one complete F0..F7 message to the host
 *   ota_frame_get(&p, &n)      next received SysEx (7-bit bytes between F0/F7), 0 if none
 *   ota_frame_done()           release it
 *   ota_now_ms(), ota_idle()   time; called while waiting (watchdog, USB)
 *   ota_erase(off) ota_prog(off, p, n) ota_fread(off, p, n)   flash, 0 = ok
 *   ota_show(step, code)       progress / result for the screen
 *   ota_commit(parm)           write RAM record + reset (never returns on hardware)
 */
#if BOARD_SMK37
/* SMK-37 Pro: the last 5 sectors of the stock VM (0xBB000..0xBFFFF, FL_OTA in fm1_flash.h), below BTIF /
 * USRTRIM 0xC0000..0xC1FFF; the update loader may drop records only below 0xC0000 (ldr_core.c) */
#define OTA_AREA 0x000BB000u                     /* staged loader, 5 x 4 KiB */
#define OTA_AREA_LEN 0x5000u
#define OTA_RES (OTA_AREA + OTA_AREA_LEN - 0x100u)  /* 0xBFF00 = 4K boundary - 256: SPL scan */
#ifndef SMK_MODEL
#define SMK_MODEL "SMK-37 Pro"                   /* (fm1_cc.h) */
#endif
#define OTA_PARM_ID "ota-" SMK_MODEL "_016"       /* the stock app's parm identity (Pro 18 B, Elite 20 B) */
_Static_assert(OTA_AREA + OTA_AREA_LEN <= 0xC0000u && OTA_AREA >= 0x9D000u, "SMK: OTA area outside the VM");
#else
#define OTA_AREA 0x000E0000u                     /* staged loader, 5 x 4 KiB */
#define OTA_AREA_LEN 0x5000u
#define OTA_RES (OTA_AREA + OTA_AREA_LEN - 0x100u)  /* 0xE4F00 = 4K boundary - 256: SPL scan */
#define OTA_PARM_ID "ota-FM-1_015"
#endif
#define OTA_LDR_HCRC 0xEBAAu                     /* official update loader (usb_hid_ota.bin) */
#define OTA_LDR_DCRC 0x5881u
#define OTA_LDR_LEN 0x4DE1u
#define OTA_FRAME_MAX 640u                       /* 512-B response = 605 wire bytes */

static int ota_wire_send(const uint8_t *p, uint32_t n);
static int ota_frame_get(const uint8_t **p, uint32_t *n);
static void ota_frame_done(void);
static uint32_t ota_now_ms(void);
static void ota_idle(void);
static int ota_erase(uint32_t off);
static int ota_prog(uint32_t off, const void *p, uint32_t n);
static int ota_fread(uint32_t off, void *p, uint32_t n);
static void ota_show(uint32_t step, int32_t code);
static void ota_commit(const uint8_t *parm);

static uint32_t ota_rd16(const uint8_t *p) { return (uint32_t)p[0] | (uint32_t)p[1] << 8; }
static uint32_t ota_rd24(const uint8_t *p) { return ota_rd16(p) | (uint32_t)p[2] << 16; }
static uint32_t ota_rd32(const uint8_t *p) { return ota_rd24(p) | (uint32_t)p[3] << 24; }
static void ota_wr16(uint8_t *p, uint32_t v) { p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8); }
static void ota_wr32(uint8_t *p, uint32_t v) { ota_wr16(p, v); ota_wr16(p + 2, v >> 16); }

static uint32_t ota_crc16(const uint8_t *p, uint32_t n, uint32_t c)   /* poly 0x1021, init 0 */
{
    uint32_t i;
    while (n--) {
        c ^= (uint32_t)*p++ << 8;
        for (i = 0; i < 8u; i++)
            c = c & 0x8000u ? (c << 1) ^ 0x1021u : c << 1;
        c &= 0xFFFFu;
    }
    return c;
}

static void ota_jl_enc(uint8_t *p, uint32_t n)   /* UFW header cipher, key 0xFFFF */
{
    uint32_t k = 0xFFFFu;
    while (n--) {
        *p++ ^= (uint8_t)k;
        k = ((k << 1) ^ (k & 0x8000u ? 0x1021u : 0u)) & 0xFFFFu;
    }
}

/* 8-to-7, LSB first */
static uint32_t ota_pack7(const uint8_t *in, uint32_t n, uint8_t *out)
{
    uint32_t acc = 0, nb = 0, o = 0;
    while (n--) {
        acc |= (uint32_t)*in++ << nb;
        nb += 8u;
        while (nb >= 7u) {
            out[o++] = (uint8_t)(acc & 0x7Fu);
            acc >>= 7;
            nb -= 7u;
        }
    }
    if (nb)
        out[o++] = (uint8_t)(acc & 0x7Fu);
    return o;
}

static uint32_t ota_unpack7(const uint8_t *in, uint32_t n, uint8_t *out, uint32_t max)
{
    uint32_t acc = 0, nb = 0, o = 0;
    while (n--) {
        acc |= (uint32_t)(*in++ & 0x7Fu) << nb;
        nb += 7u;
        if (nb >= 8u) {
            if (o < max)
                out[o] = (uint8_t)acc;
            o++;
            acc >>= 8;
            nb -= 8u;
        }
    }
    return o;
}

static uint8_t ota_msg[8 + 32], ota_wire[2 + 48];
#ifdef OTA_SCRATCH                               /* the app: after the session buffers in the scratch */
#define ota_dec (OTA_SCRATCH + OTA_DEC_OFF)
#else
static uint8_t ota_dec[OTA_FRAME_MAX];           /* decoded host message */
#endif

static int ota_send_msg(uint32_t cmd, const uint8_t *body, uint32_t n)   /* n <= 32 */
{
    uint32_t i, s = 0, w;
    ota_msg[0] = 0;
    ota_msg[1] = 0x59;
    ota_msg[2] = (uint8_t)cmd;
    ota_msg[3] = (uint8_t)n;
    ota_msg[4] = 0;
    ota_msg[5] = 0;
    for (i = 0; i < n; i++) {
        ota_msg[6 + i] = body[i];
        s += body[i];
    }
    ota_msg[6 + n] = (uint8_t)~s;
    ota_wire[0] = 0xF0;
    w = 1u + ota_pack7(ota_msg, 7u + n, ota_wire + 1);
    ota_wire[w++] = 0xF7;
    return ota_wire_send(ota_wire, w);
}

static void ota_reply_identity(void)
{
    static const char ID[] = FELUCCA_ID;         /* == the package marker string */
    uint8_t id[27];
    uint32_t i;
    for (i = 0; i < sizeof id; i++)
        id[i] = i < sizeof ID - 1u ? (uint8_t)ID[i] : 0;
    ota_send_msg(0x11, id, sizeof id);
}

/* decode the pending frame; returns its decoded length (0 = not ours) */
static uint32_t ota_take(void)
{
    const uint8_t *p;
    uint32_t n, d, s = 0, i;
    if (!ota_frame_get(&p, &n))
        return 0;
    d = ota_unpack7(p, n, ota_dec, OTA_FRAME_MAX);
    ota_frame_done();
    if (d < 7u || d > OTA_FRAME_MAX || ota_dec[0] != 0 || ota_dec[1] != 0x59 || ota_rd24(ota_dec + 3) + 7u != d)
        return 0;
    for (i = 6; i + 1u < d; i++)
        s += ota_dec[i];
    if ((uint8_t)~s != ota_dec[d - 1u])
        return 0;
    return d;
}

/* main loop, outside a session: answer handshakes */
static void ota_service(void)
{
    uint32_t d = ota_take();
    if (d == 7u && ota_dec[2] == 0x11)
        ota_reply_identity();
}

/* one read request (3 tries x 5 s); data -> dst */
static uint32_t ota_deadline;                    /* 0 = none; else ota_now_ms() limit of the session */

static int ota_read(uint32_t addr, uint8_t *dst, uint32_t len)
{
    uint8_t q[8];
    uint32_t tries, t, d, i;
    if (ota_deadline && (int32_t)(ota_now_ms() - ota_deadline) > 0)
        return -1;                                  /* the whole session took too long: give up */
    q[0] = 0;
    ota_wr32(q + 1, addr);
    q[5] = (uint8_t)len;
    q[6] = (uint8_t)(len >> 8);
    q[7] = 0;
    for (tries = 0; tries < 3u; tries++) {
        if (ota_send_msg(0x30, q, 8))
            return -1;
        for (t = ota_now_ms(); ota_now_ms() - t < 5000u;) {
            ota_idle();
            d = ota_take();
            if (!d)
                continue;
            if (d == 7u && ota_dec[2] == 0x11) {
                ota_reply_identity();
                continue;
            }
            if (d == len + 15u && ota_dec[2] == 0x30 && ota_rd24(ota_dec + 3) == len + 8u &&
                ota_rd32(ota_dec + 7) == addr && ota_rd24(ota_dec + 11) == len) {
                for (i = 0; i < len; i++)
                    dst[i] = ota_dec[14 + i];
                return 0;
            }
        }
    }
    return -1;
}

static int ota_memeq(const uint8_t *a, const uint8_t *b, uint32_t n)
{
    while (n--)
        if (*a++ != *b++)
            return 0;
    return 1;
}

/* JLFS head "LOADER.BIN" in front of the staged loader (vm_update_defrag), written last */
static int ota_stage_head(uint32_t len)
{
    static const char NAME[16] = "LOADER.BIN";
    uint8_t h[32];
    uint32_t i;
    for (i = 0; i < 32u; i++)
        h[i] = 0;
    ota_wr16(h + 2, 0xFFFFu);
    ota_wr32(h + 4, OTA_AREA);
    ota_wr32(h + 8, len + 32u);
    h[12] = 0x41u;
    h[13] = 0xFFu;
    ota_wr16(h + 14, 0xFFFFu);
    for (i = 0; i < 16u; i++)
        h[16 + i] = (uint8_t)NAME[i];
    ota_wr16(h, ota_crc16(h + 2, 30, 0));
    return ota_prog(OTA_AREA, h, 32);
}

/* UFW header + entry list (hdr: 1 KiB) from the host -> offset / length of
 * flash.bin (entry type 0) and ota.bin (type 100), 0 if absent; -1 read, -2 CRC */
static int ota_ufw(uint8_t *hdr, uint32_t *fl_off, uint32_t *fl_len, uint32_t *ota_off, uint32_t *ota_len)
{
    uint32_t i, nent;
    *fl_off = *fl_len = *ota_off = *ota_len = 0;
    if (ota_read(0, hdr, 512) || ota_read(512, hdr + 512, 512))
        return -1;
    ota_jl_enc(hdr, 0x40);
    nent = ota_rd16(hdr + 8);
    if (ota_crc16(hdr + 2, 0x3E, 0) != ota_rd16(hdr) || nent == 0 || nent > 11u ||
        ota_crc16(hdr + 0x40, nent * 0x50u, 0) != ota_rd16(hdr + 2))
        return -2;
    for (i = 0; i < nent; i++) {
        uint8_t *e = hdr + 0x40 + i * 0x50u;
        ota_jl_enc(e, 0x50);
        if (ota_rd16(e) == 0) {                             /* flash.bin */
            *fl_off = ota_rd32(e + 8);
            *fl_len = ota_rd32(e + 12);
        }
        if (ota_rd16(e) == 100) {                           /* ota.bin */
            *ota_off = ota_rd32(e + 8);
            *ota_len = ota_rd32(e + 12);
        }
    }
    return 0;
}

static int ota_stage(void)                       /* steps 1..6; 0 = host said success */
{
#ifdef OTA_SCRATCH                     /* the app: a main-loop scratch that it shares (2 KiB used) */
    uint8_t *const hdr = OTA_SCRATCH, *const b = hdr + 0x400, *const mine = b + 512;
#else
    static uint8_t hdr[0x400], b[512], mine[512];
#endif
    uint32_t i, n, ota_off, ota_len, fl_off, fl_len, c, len, own, official;
    int rc;
    /* 1. UFW header + entry list */
    ota_show(1, 0);
    if ((rc = ota_ufw(hdr, &fl_off, &fl_len, &ota_off, &ota_len)) != 0)
        return rc;
    if (!fl_off || !ota_off)
        return -3;
    /* 2. which loader: the official one (known CRCs; it rewrites the whole flash.bin
     *    including the head) or Felucca's own (app area only, checks the chip key) */
    if (ota_read(ota_off, b, 512))
        return -6;
    len = ota_rd32(b + 8);
    if (ota_crc16(b + 2, 30, 0) != ota_rd16(b) || ota_rd32(b + 4) != 0x20u || b[12] != 0x41u ||
        ota_len != len + 0x20u || len > OTA_AREA_LEN - 0x200u || ota_crc16(b + 0x22, 30, 0) != ota_rd16(b + 0x20) ||
        ota_rd32(b + 0x20 + 8) != 0x01C0A800u)
        return -7;
    official = ota_rd16(b) == OTA_LDR_HCRC && ota_rd16(b + 2) == OTA_LDR_DCRC && len == OTA_LDR_LEN;
    for (i = 0x48, own = 0; i + 16u <= 0x48u + 64u && !own; i++)    /* first LZ4 literals: crt0_ldr.S */
        own = ota_memeq(b + i, (const uint8_t *)"FELUCCA-LOADER-1", 16) && ota_rd32(b + 0x20 + 4) <= 0x14000u;
    if (!official && !own)
        return -7;
    if (official) {                    /* the official loader writes the head: it must equal ours */
        ota_show(2, 0);
        for (i = 0; i < 0x4000u; i += 512u) {
            if (ota_read(fl_off + i, b, 512) || ota_fread(i, mine, 512))
                return -4;
            if (!ota_memeq(b, mine, 512))
                return -5;
        }
    }
    /* 4. stage the package's loader: erase, body, verify, head last */
    ota_show(3, 0);
    if (ota_read(ota_off, b, 512))
        return -6;
    c = ota_rd16(b + 2);                                    /* outer dcrc of the body */
    for (i = 0; i < OTA_AREA_LEN; i += 0x1000u)
        if (ota_erase(OTA_AREA + i))
            return -8;
    {
        uint32_t crc = 0;
        for (i = 0; i < len; i += n) {
            n = len - i > 512u ? 512u : len - i;
            if (ota_read(ota_off + 0x20u + i, b, n))
                return -9;
            crc = ota_crc16(b, n, crc);
            if (ota_prog(OTA_AREA + 32u + i, b, n))
                return -10;
        }
        if (crc != c)
            return -11;
        for (i = 0, crc = 0; i < len; i += n) {             /* read back from flash */
            n = len - i > 512u ? 512u : len - i;
            if (ota_fread(OTA_AREA + 32u + i, b, n))
                return -11;
            crc = ota_crc16(b, n, crc);
        }
        if (crc != c)
            return -11;
    }
    if (ota_stage_head(len))
        return -12;
    /* 6. the host confirms: nothing is committed without it */
    ota_show(4, 0);
    for (i = 0; i < 4u; i++)
        if (!ota_read(0xE0000000u, b, 8) && ota_memeq(b, (const uint8_t *)"success", 8))
            return 0;
    return -13;
}

static void ota_unstage(void)
{
    uint32_t i;
    for (i = 0; i < OTA_AREA_LEN; i += 0x1000u)
        ota_erase(OTA_AREA + i);
}

/* returns only when nothing was committed (refused, failed, or dry run) */
static int ota_session(void)
{
#ifdef OTA_SCRATCH                              /* the app: the scratch tail, after ota_dec */
    uint8_t *const parm = OTA_SCRATCH + OTA_PARM_OFF;
#else
    static uint8_t parm[112];
#endif
    uint8_t back[112];
    uint32_t i;
    int rc;
    ota_deadline = ota_now_ms() + 120000u;          /* step 1 normally takes ~5 s; a stalled host gives up after 2 min */
    rc = ota_stage();
    if (rc) {
        ota_unstage();
        ota_show(9, rc);
        return rc;
    }
    /* 5./7. UPDATA_PARM (update_mode_api_v2 layout), flash copy first */
    for (i = 0; i < 112u; i++)
        parm[i] = 0;
    ota_wr16(parm + 2, 0x5A0Du);
    ota_wr16(parm + 4, 0x5A01u);
    ota_wr16(parm + 6, 0x5441u);
    for (i = 0; i < sizeof OTA_PARM_ID - 1u; i++)    /* FM-1 12 B, SMK 18 B; zero up to +0x27 */
        parm[8 + i] = (uint8_t)OTA_PARM_ID[i];    /* the loader's own USB identity */
    ota_wr32(parm + 72, OTA_AREA);
    ota_wr16(parm, ota_crc16(parm + 2, 78, 0));
#if FELUCCA_OTA_DRYRUN
    ota_unstage();
    ota_show(9, 1);                                 /* 1 = dry run complete */
    return 1;
#endif
#ifndef FELUCCA_OTA_RAMONLY
#define FELUCCA_OTA_RAMONLY 0                       /* 1: RAM record only, no power-loss resume (a power
                                                     * cycle leaves a broken loader behind) */
#endif
    if (!FELUCCA_OTA_RAMONLY && (ota_prog(OTA_RES, parm, 112u) || ota_fread(OTA_RES, back, sizeof back) ||
        !ota_memeq(back, parm, 112u))) {
        ota_unstage();
        ota_show(9, -14);
        return -14;
    }
    ota_show(5, 0);
    ota_commit(parm);
    return 0;
}

/* boot: a staging area left over (we are running, so the update finished or
 * never started): erase it so the SPL does not re-enter the loader */
static int ota_boot_cleanup(void)
{
    uint8_t a[4], r[8];
    uint32_t i, used = 0;
    if (ota_fread(OTA_AREA, a, 4) || ota_fread(OTA_RES, r, 8))
        return -1;
    for (i = 0; i < 4u; i++)
        used |= a[i] != 0xFFu;
    for (i = 0; i < 8u; i++)
        used |= r[i] != 0xFFu;
    if (used)
        ota_unstage();
    return (int)used;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Full audio CQ must retain bass Note On (C_BON) under param flood.

Sibling of engine_cq_boff_overflow_test.py (#588) / brk (#596). Extracts
production cq_put from engine.c. A full ring of params must still accept
C_BON by displacing a disposable param/drum entry. C_BOFF and C_BRK release
remain protected and must not be displaced by a late Note On.
"""
from pathlib import Path
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
e = (ROOT / "firmware/src/app/engine.c").read_text()
ring = e[e.index("enum { C_PARAM_T0 = 0, C_DRUM") : e.index("/* ------------------------------------------------------------ params --- */")]
src = (
    "#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n"
    + "static uint32_t plat_cq_lock(void) { return 0; }\nstatic void plat_cq_unlock(uint32_t s) { (void)s; }\n"
    + ring
    + r"""
static int count_type(uint32_t type)
{
    unsigned n = 0;
    for (uint32_t i = cq_r; i != cq_w; i++)
        n += (cq[i % CQ] >> 28) == type;
    return (int)n;
}

static int count_brk_down(uint32_t down)
{
    unsigned n = 0;
    for (uint32_t i = cq_r; i != cq_w; i++) {
        uint32_t w = cq[i % CQ];
        if ((w >> 28) == C_BRK && ((w >> 12) & 0xFFu) == down)
            n++;
    }
    return (int)n;
}

static int expect_bon_kept(void)
{
    cq_w = cq_r = 0;
    for (unsigned i = 0; i < CQ; i++)
        cq_put(C_PARAM_T0, 0, 0, i);
    cq_put(C_BON, 0, 60, 400);
    if (cq_w - cq_r != CQ)
        return 11;
    if (count_type(C_BON) != 1)
        return 12;
    if (count_type(C_PARAM_T0) != (int)CQ - 1)
        return 13;
    return 0;
}

static int expect_boff_still_kept(void)
{
    cq_w = cq_r = 0;
    cq_put(C_BON, 0, 60, 400);
    for (unsigned i = 0; i < CQ - 1u; i++)
        cq_put(C_PARAM_T0, 0, 0, i);
    cq_put(C_BOFF, 0, 0, 0);
    if (count_type(C_BON) != 1)
        return 21;
    if (count_type(C_BOFF) != 1)
        return 22;
    return 0;
}

static int expect_bon_does_not_displace_boff(void)
{
    cq_w = cq_r = 0;
    cq_put(C_BOFF, 0, 0, 0);
    for (unsigned i = 0; i < CQ - 1u; i++)
        cq_put(C_PARAM_T0, 0, 0, i);
    cq_put(C_BON, 1, 61, 400);
    if (count_type(C_BOFF) != 1)
        return 31;
    if (count_type(C_BON) != 1)
        return 32;
    return 0;
}

static int expect_bon_does_not_displace_brk_release(void)
{
    cq_w = cq_r = 0;
    cq_put(C_BRK, 3, 0, 0);                 /* release already queued */
    for (unsigned i = 0; i < CQ - 1u; i++)
        cq_put(C_PARAM_T0, 0, 0, i);
    cq_put(C_BON, 0, 60, 400);
    if (count_brk_down(0) != 1)
        return 41;
    if (count_type(C_BON) != 1)
        return 42;
    return 0;
}

static int expect_param_still_drops(void)
{
    cq_w = cq_r = 0;
    for (unsigned i = 0; i < CQ; i++)
        cq_put(C_PARAM_T0, 0, 0, i);
    cq_put(C_PARAM_T0, 0, 0, 0xABC);
    if (cq_w - cq_r != CQ)
        return 51;
    for (uint32_t i = cq_r; i != cq_w; i++) {
        if ((cq[i % CQ] & 0xFFFu) == 0xABCu)
            return 52;
    }
    return 0;
}

int main(void)
{
    int rc;
    if ((rc = expect_bon_kept()) != 0) {
        printf("FAIL bon-kept rc=%d depth=%u bon=%d param=%d\n",
               rc, (unsigned)(cq_w - cq_r), count_type(C_BON), count_type(C_PARAM_T0));
        return 1;
    }
    if ((rc = expect_boff_still_kept()) != 0) {
        printf("FAIL boff-still-kept rc=%d\n", rc);
        return 2;
    }
    if ((rc = expect_bon_does_not_displace_boff()) != 0) {
        printf("FAIL bon-vs-boff rc=%d\n", rc);
        return 3;
    }
    if ((rc = expect_bon_does_not_displace_brk_release()) != 0) {
        printf("FAIL bon-vs-brk-rel rc=%d\n", rc);
        return 4;
    }
    if ((rc = expect_param_still_drops()) != 0) {
        printf("FAIL param-drop rc=%d\n", rc);
        return 5;
    }
    puts("ok");
